#!/usr/bin/env bash
# Feeds each guard the PreToolUse JSON Claude Code sends and prints one line per case. `decision`
# reads the deny shape; `shape` names what came back: `claude` for the PreToolUse deny, `silent` for
# no output, `other` for anything else.
set -u
H=${HOOKS:-$HOME/.dotfiles/claude/hooks}
# GUARD_BASH runs the guards under that interpreter instead of their shebang; the last line reruns
# every case under macOS's bash 3.2, which `env bash` resolves to when Homebrew's is not on PATH.
guard() { ${GUARD_BASH:-} "$H/$1"; }
decision() { local out; out=$(cat); [[ -z $out ]] && echo allow || jq -r '.hookSpecificOutput.permissionDecision // "allow"' <<<"$out" 2>/dev/null; }
shape() { local out; out=$(cat); [[ -z $out ]] && echo silent || jq -r 'if .hookSpecificOutput then "claude" else "other" end' <<<"$out" 2>/dev/null; }
fail=0
case_() { # name expected actual
  if [[ $2 == "$3" ]]; then echo "PASS $1"; else echo "FAIL $1: expected $2, got '$3'"; fail=1; fi
}
payload() { # event tool key value [cwd]
  jq -cn --arg e "$1" --arg t "$2" --arg k "$3" --arg v "$4" --arg c "${5:-}" '{hook_event_name:$e,tool_name:$t,tool_input:{($k):$v},cwd:$c}'
}
qv() { payload PreToolUse "$1" "$2" "$3" "${4:-}" | guard guard-queue-views.sh | decision; }
qv2() { jq -cn --arg t "$1" --arg a "$2" --arg b "$3" '{hook_event_name:"PreToolUse",tool_name:$t,tool_input:{file_path:$a,notebook_path:$b},cwd:""}' | guard guard-queue-views.sh | decision; } # <tool> <file_path> <notebook_path>
mg() { payload PreToolUse Bash command "$1" | guard guard-merge.sh | decision; }
rd() { payload PreToolUse Bash command "$1" | guard guard-repo-delete.sh | decision; }
pg() { payload PreToolUse Bash command "$1" "${2:-}" | guard guard-push.sh | decision; } # <command> [cwd]
tk() { ${GUARD_BASH:-bash} -c '. "$1/guard-common.sh"; seg() { local w; for w in "$@"; do printf "[%s]" "${w//$SUBST/\$()}"; done; printf "\n"; }; shell_segments "$2" seg' tk "$H" "$1"; } # <command>: one line of [word]s per segment, a substitution shown as $()
unreadable() { jq -cn --arg e "$1" --arg t "$2" '{hook_event_name:$e,tool_name:$t,tool_input:"x",cwd:""}'; } # <event> <tool>: tool_input is a string, so jq reads no command or path from it
many() { local i; for ((i = 0; i < $1; i++)); do printf "$2" "$i"; done; } # <n> <printf format>: the format n times, %d the index
V=$HOME/obsidian/SecondBrain/projects/ClaudeOS
Q=$HOME/.local/share/vault-queues/ClaudeOS
case_ "edit vault view"        deny  "$(qv Edit file_path "$V/Queue.md")"
case_ "write vault view"       deny  "$(qv Write file_path "$V/Queue.md")"
case_ "write authority"        deny  "$(qv Write file_path "$Q/Queue.md")"
T=$(mktemp -d)/vault-queues
mkdir -p "$T/.claudeos/edit" "$T/ClaudeOS" "$T/Tribemap"
touch "$T/.claudeos/edit/ClaudeOS"
case_ "edit authority, no session"    deny  "$(qv Edit file_path "$T/Tribemap/Queue.md")"
case_ "edit authority, open session"  allow "$(qv Edit file_path "$T/ClaudeOS/Queue.md")"
case_ "write authority, open session" deny  "$(qv Write file_path "$T/ClaudeOS/Queue.md")"
case_ "bash authority, open session"  deny  "$(qv Bash command "sed -i '' 's/a/b/' $T/ClaudeOS/Queue.md")"
case_ "edit session via dotdot"       deny  "$(qv Edit file_path "$T/ClaudeOS/../Tribemap/Queue.md")"
case_ "edit dotdot into session"      allow "$(qv Edit file_path "$T/Tribemap/../ClaudeOS/Queue.md")"
case_ "write view via dot"            deny  "$(qv Write file_path "$V/./Queue.md")"
case_ "write view via dotdot"         deny  "$(qv Write file_path "$V/plans/../Queue.md")"
case_ "dotdot past root"              deny  "$(qv Edit file_path "/../../$T/Tribemap/Queue.md")"
case_ "edit relative, open session"   deny  "$(qv Edit file_path "vault-queues/ClaudeOS/Queue.md")"
O=$(mktemp -d)/SecondBrain/projects
mkdir -p "$O/.claudeos/edit" "$O/ClaudeOS" "$O/Tribemap"
touch "$O/.claudeos/edit/ClaudeOS"
case_ "edit one-folder authority, open session" allow "$(qv Edit file_path "$O/ClaudeOS/Queue.md")"
case_ "edit one-folder authority, no session"   deny  "$(qv Edit file_path "$O/Tribemap/Queue.md")"
case_ "edit lower-case name, open session"              deny  "$(qv Edit file_path "$T/ClaudeOS/queue.md")"
case_ "edit followups view"                     deny  "$(qv Edit file_path "$V/Followups.md")"
case_ "write followups view"                    deny  "$(qv Write file_path "$V/Followups.md")"
case_ "write followups authority"               deny  "$(qv Write file_path "$Q/Followups.md")"
case_ "edit followups authority, open session"  deny  "$(qv Edit file_path "$T/ClaudeOS/Followups.md")"
case_ "edit one-folder followups, open session" deny  "$(qv Edit file_path "$O/ClaudeOS/Followups.md")"
case_ "edit lower-case followups view"          deny  "$(qv Edit file_path "$V/followups.md")"
case_ "edit relative followups, cwd in view"    deny  "$(qv Edit file_path Followups.md "$V")"
case_ "edit relative followups, no cwd"         deny  "$(qv Edit file_path Followups.md)"
case_ "multiedit vault view"                    deny  "$(qv MultiEdit file_path "$V/Queue.md")"
case_ "multiedit followups authority"           deny  "$(qv MultiEdit file_path "$Q/Followups.md")"
case_ "multiedit authority, open session"       deny  "$(qv MultiEdit file_path "$T/ClaudeOS/Queue.md")"
case_ "notebookedit vault view"                 deny  "$(qv NotebookEdit notebook_path "$V/Queue.md")"
case_ "notebookedit followups authority"        deny  "$(qv NotebookEdit notebook_path "$Q/Followups.md")"
case_ "notebookedit authority, open session"    deny  "$(qv NotebookEdit notebook_path "$T/ClaudeOS/Queue.md")"
case_ "notebookedit relative, no cwd"           deny  "$(qv NotebookEdit notebook_path Queue.md)"
case_ "notebookedit elsewhere"                  allow "$(qv NotebookEdit notebook_path "$HOME/code/claudeos/Queue.md")"
case_ "notebookedit empty file_path, guarded notebook" deny  "$(qv2 NotebookEdit "" "$V/Queue.md")"
case_ "notebookedit other file_path, guarded notebook" deny  "$(qv2 NotebookEdit "$HOME/x.ipynb" "$Q/Followups.md")"
case_ "notebookedit guarded file_path, empty notebook" deny  "$(qv2 NotebookEdit "$V/Queue.md" "")"
case_ "notebookedit two unguarded paths"        allow "$(qv2 NotebookEdit "$HOME/x.ipynb" "$HOME/y.ipynb")"
case_ "queue guard matcher"                    "Write|Edit|MultiEdit|NotebookEdit|Bash" "$(jq -r '.hooks.PreToolUse[] | select(any(.hooks[]; .command | endswith("guard-queue-views.sh"))) | .matcher' "$H/../settings.json")"
rm -rf "${T%/vault-queues}"
case_ "bash sed authority"     deny  "$(qv Bash command "sed -i 's/a/b/' $Q/Queue.md")"
case_ "bash heredoc view"      deny  "$(qv Bash command "cat > $V/Queue.md <<'X'")"
case_ "bash sed relative view" deny  "$(qv Bash command "sed -i '' 's/a/b/' projects/ClaudeOS/Queue.md")"
case_ "bash icloud view"       deny  "$(qv Bash command "sed -i '' 's/a/b/' '$HOME/Library/Mobile Documents/iCloud~md~obsidian/Documents/SecondBrain/projects/ClaudeOS/Queue.md'")"
case_ "edit inbox"             allow "$(qv Edit file_path "$V/Inbox.md")"
case_ "edit a plan"            allow "$(qv Edit file_path "$V/plans/2026-09-16-mechanical-rules.md")"
case_ "bash queue dump"        allow "$(qv Bash command "claudeos queue dump ClaudeOS")"
case_ "bash grep docs"         allow "$(qv Bash command "grep -n Queue.md ~/obsidian/SecondBrain/CLAUDE.md")"
case_ "bash unrelated"         allow "$(qv Bash command "cat README.md")"
C=$HOME/code/claudeos
I="$HOME/Library/Mobile Documents/iCloud~md~obsidian/Documents/SecondBrain/projects/ClaudeOS"
case_ "bash sed bare name, cwd in view"       deny  "$(qv Bash command "sed -i '' 's/a/b/' Queue.md" "$V")"
case_ "write followups elsewhere"               allow "$(qv Write file_path "$C/Followups.md")"
case_ "bash sed followups authority"            deny  "$(qv Bash command "sed -i '' 's/a/b/' $Q/Followups.md")"
case_ "bash sed followups bare, cwd in view"    deny  "$(qv Bash command "sed -i '' 's/a/b/' Followups.md" "$V")"
case_ "bash cd into view, sed followups"        deny  "$(qv Bash command "cd $V; sed -i '' 's/a/b/' Followups.md" "$C")"
case_ "bash followups bracket glob, cwd in view" deny "$(qv Bash command "cp /tmp/x Followups.m[d]" "$V")"
case_ "bash followups paren glob, cwd in view"  deny  "$(qv Bash command "cp /tmp/x Followups.m(d|x)" "$V")"
case_ "bash redirect onto followups, cwd in view" deny "$(qv Bash command "cat x > Followups.md" "$V")"
case_ "bash cat followups, cwd in view"         allow "$(qv Bash command "cat Followups.md" "$V")"
case_ "bash grep followups view"                allow "$(qv Bash command "grep -n x $V/Followups.md")"
case_ "bash sed followups elsewhere"            allow "$(qv Bash command "sed -i '' 's/a/b/' Followups.md" "$C")"
case_ "followups deny names the tool"           1     "$(payload PreToolUse Write file_path "$V/Followups.md" | guard guard-queue-views.sh | grep -c 'claudeos followup add|list|tick')"
case_ "bash append bare name, cwd in view"    deny  "$(qv Bash command "echo x >> Queue.md" "$V")"
case_ "bash append unspaced, cwd in view"     deny  "$(qv Bash command "echo x >>Queue.md" "$V")"
case_ "bash dot-slash name, cwd in view"      deny  "$(qv Bash command "sed -i '' 's/a/b/' ./Queue.md" "$V")"
case_ "bash dotdot name, cwd under view"      deny  "$(qv Bash command "sed -i '' 's/a/b/' ../Queue.md" "$V/plans")"
case_ "bash bare name, cwd in icloud view"    deny  "$(qv Bash command "sed -i '' 's/a/b/' Queue.md" "$I")"
case_ "bash project name, cwd authority root" deny  "$(qv Bash command "sed -i '' 's/a/b/' ClaudeOS/Queue.md" "${Q%/*}")"
case_ "bash cd into view"                     deny  "$(qv Bash command "cd $V && sed -i '' 's/a/b/' Queue.md" "$C")"
case_ "bash cd into view, no cwd"             deny  "$(qv Bash command "cd $V && sed -i '' 's/a/b/' Queue.md")"
case_ "bash cd chain into view"               deny  "$(qv Bash command "cd ~/obsidian/SecondBrain && cd projects/ClaudeOS && sed -i '' 's/a/b/' Queue.md" "$C")"
case_ "bash cd semicolon chain into view"     deny  "$(qv Bash command "cd ~/obsidian/SecondBrain;cd projects/ClaudeOS;sed -i '' 's/a/b/' Queue.md" "$C")"
case_ "bash cd quoted icloud view"            deny  "$(qv Bash command "cd '$I' && sed -i '' 's/a/b/' Queue.md" "$C")"
case_ "bash cd double-quoted icloud view"     deny  "$(qv Bash command "cd \"$I\" && sed -i '' 's/a/b/' Queue.md" "$C")"
case_ "bash cd in subshell into authority"    deny  "$(qv Bash command "(cd $Q; sed -i 's/a/b/' Queue.md)" "$C")"
case_ "bash unbalanced quote, cwd in view"    deny  "$(qv Bash command "echo 'x >> Queue.md" "$V")"
case_ "bash empty command, cwd in view"       allow "$(qv Bash command "" "$V")"
case_ "bash long command, bare name elsewhere" allow "$(qv Bash command "echo $(head -c 40000 /dev/zero | tr '\0' a); cat Queue.md" "$C")"
case_ "bash bare name elsewhere"              allow "$(qv Bash command "cat Queue.md" "$C/testdata")"
case_ "bash bare name, no cwd"                allow "$(qv Bash command "cat Queue.md")"
case_ "bash grep pattern elsewhere"           allow "$(qv Bash command "grep -rn Queue.md internal" "$C")"
case_ "bash cd elsewhere"                     allow "$(qv Bash command "cd internal/queue && cat testdata/Queue.md" "$C")"
case_ "bash other basename, cwd in view"      allow "$(qv Bash command "cat OldQueue.md" "$V")"
case_ "bash grep pattern, cwd vault root"     allow "$(qv Bash command "grep -n Queue.md CLAUDE.md" "$HOME/obsidian/SecondBrain")"
R=$HOME/obsidian/SecondBrain
case_ "edit lower-case name"                   deny  "$(qv Edit file_path "$V/queue.md")"
case_ "write lower-case name"                  deny  "$(qv Write file_path "$V/queue.md")"
case_ "write upper-case name"                  deny  "$(qv Write file_path "$V/QUEUE.MD")"
case_ "write lower-case directories"           deny  "$(qv Write file_path "$HOME/obsidian/secondbrain/Projects/claudeos/Queue.md")"
case_ "bash lower-case name, absolute"         deny  "$(qv Bash command "sed -i '' 's/a/b/' $V/queue.md")"
case_ "bash lower-case name, cwd in view"      deny  "$(qv Bash command "sed -i '' 's/a/b/' queue.md" "$V")"
case_ "bash empty quotes in name, absolute"    deny  "$(qv Bash command "sed -i '' 's/a/b/' $V/Que\"\"ue.md")"
case_ "bash backslash in name, absolute"       deny  "$(qv Bash command "sed -i '' 's/a/b/' $V/Que\\ue.md")"
case_ "bash quoted pieces, absolute"           deny  "$(qv Bash command "sed -i '' 's/a/b/' \"$V\"/'Queue.md'")"
case_ "bash continuation in name, absolute"    deny  "$(qv Bash command "$(printf 'sed -i "" s/a/b/ %s/Que\\\nue.md' "$V")")"
case_ "bash empty quotes in name, cwd in view" deny  "$(qv Bash command 'sed -i "" s/a/b/ Que""ue.md' "$V")"
case_ "bash cd -- into view"                   deny  "$(qv Bash command "cd -- $V && sed -i '' 's/a/b/' Queue.md" "$C")"
case_ "bash cd -P into view"                   deny  "$(qv Bash command "cd -P $V && sed -i '' 's/a/b/' Queue.md" "$C")"
case_ "bash cd -L into view"                   deny  "$(qv Bash command "cd -L $V && sed -i '' 's/a/b/' Queue.md" "$C")"
case_ "bash cd -P -- into view"                deny  "$(qv Bash command "cd -P -- $V && sed -i '' 's/a/b/' Queue.md" "$C")"
case_ "bash cd half-quoted home"               deny  "$(qv Bash command 'cd "$HOME"/obsidian/SecondBrain/projects/ClaudeOS && sed -i "" s/a/b/ Queue.md' "$C")"
case_ "bash cd half-quoted segment"            deny  "$(qv Bash command "cd ~/obsidian/\"SecondBrain\"/projects/ClaudeOS && sed -i '' 's/a/b/' Queue.md" "$C")"
case_ "bash cd escaped space, icloud view"     deny  "$(qv Bash command "cd $HOME/Library/Mobile\\ Documents/iCloud~md~obsidian/Documents/SecondBrain/projects/ClaudeOS && sed -i '' 's/a/b/' Queue.md" "$C")"
case_ "bash cd continuation into view"         deny  "$(qv Bash command "$(printf 'cd \\\n%s && sed -i "" s/a/b/ Queue.md' "$V")" "$C")"
case_ "bash dd of=, cwd in view"               deny  "$(qv Bash command "dd if=/dev/null of=Queue.md" "$V")"
case_ "bash --output=, cwd in view"            deny  "$(qv Bash command "curl -s x --output=Queue.md" "$V")"
case_ "bash brace list, cwd in view"           deny  "$(qv Bash command "sed -i '' 's/a/b/' {Queue.md,Inbox.md}" "$V")"
case_ "bash brace suffix, cwd in view"         deny  "$(qv Bash command "sed -i '' 's/a/b/' Queue.{md,bak}" "$V")"
case_ "bash brace list in a path, cwd vault root" deny "$(qv Bash command "sed -i '' 's/a/b/' projects/ClaudeOS/{Queue,Design}.md" "$R")"
case_ "bash two brace lists, cwd vault root"   deny  "$(qv Bash command "sed -i '' 's/a/b/' projects/{ClaudeOS,Tribemap}/{Queue,Inbox}.md" "$R")"
case_ "bash bracket glob, absolute"            deny  "$(qv Bash command "sed -i '' 's/a/b/' $V/Queue.m[d]")"
case_ "bash bracket glob, cwd in view"         deny  "$(qv Bash command "sed -i '' 's/a/b/' Queue.m[d]" "$V")"
case_ "bash upper class glob, cwd in view"     deny  "$(qv Bash command "rm [[:upper:]]ueue.md" "$V")"
case_ "bash upper class followups, cwd in view" deny  "$(qv Bash command "rm [[:upper:]]ollowups.md" "$V")"
case_ "bash negated lower class, cwd in view"   deny  "$(qv Bash command "rm [![:lower:]]ueue.md" "$V")"
case_ "bash caret lower class, cwd in view"     deny  "$(qv Bash command "rm [^[:lower:]]ueue.md" "$V")"
case_ "bash upper class glob, absolute"         deny  "$(qv Bash command "rm $V/[[:upper:]]ueue.md")"
case_ "bash upper class paren glob, cwd in view" deny "$(qv Bash command "cp /tmp/x [[:upper:]]ueue.m(d|x)" "$V")"
case_ "bash redirect onto upper class, cwd in view" deny "$(qv Bash command "cat x > [[:upper:]]ueue.md" "$V")"
case_ "bash cat upper class glob, cwd in view"  allow "$(qv Bash command "cat [[:upper:]]ueue.md" "$V")"
case_ "bash question glob, cwd in view"        deny  "$(qv Bash command "sed -i '' 's/a/b/' Queue.m?" "$V")"
case_ "bash star glob, cwd in view"            deny  "$(qv Bash command "sed -i '' 's/a/b/' *.md" "$V")"
case_ "bash star glob in a path, cwd vault root" deny "$(qv Bash command "sed -i '' 's/a/b/' projects/ClaudeOS/*.md" "$R")"
case_ "bash bare star, cwd in authority"       deny  "$(qv Bash command "sed -i '' 's/a/b/' *" "$Q")"
case_ "bash 17 cd targets and a name"          deny  "$(qv Bash command "$(many 17 'cd d%d; ')cat Queue.md" "$C")"
case_ "bash 120 cd targets, 120 names"         deny  "$(qv Bash command "$(many 120 'cd d%d; ')$(many 120 'cat Queue.md; ')" "$C")"
case_ "bash 600 names elsewhere"               deny  "$(qv Bash command "$(many 600 'cat d%d/Queue.md; ')" "$C")"
case_ "bash overrun says why"                  1     "$(payload PreToolUse Bash command "$(many 17 'cd d%d; ')cat Queue.md" "$C" | guard guard-queue-views.sh | grep -c 'too many cd targets')"
case_ "bash plain deny keeps its reason"       0     "$(payload PreToolUse Bash command "sed -i '' 's/a/b/' Queue.md" "$V" | guard guard-queue-views.sh | grep -c 'too many cd targets')"
case_ "bash 16 cd targets and a name"          allow "$(qv Bash command "$(many 16 'cd d%d; ')cat Queue.md" "$C")"
case_ "bash 40 cd targets, no name"            allow "$(qv Bash command "$(many 40 'cd d%d; ')ls" "$C")"
case_ "bash 500 stars elsewhere"               allow "$(qv Bash command "printf '%s\n' $(many 500 '* ')" "$C")"
case_ "bash long word of slashes elsewhere"    allow "$(qv Bash command "echo $(many 8000 'a/')x; cd internal; cat Queue.md" "$C")"
case_ "bash 9 brace lists, cwd in view"        deny  "$(qv Bash command "sed -i '' 's/a/b/' {,}{,}{,}{,}{,}{,}{,}{,}{,}Queue.md" "$V")"
case_ "bash long brace word, cwd in view"      deny  "$(qv Bash command "sed -i '' 's/a/b/' {$(many 4100 'a'),Queue.md}" "$V")"
case_ "bash sort -o attached, cwd in view"     deny  "$(qv Bash command "sort -oQueue.md /dev/null" "$V")"
case_ "bash curl -o attached, cwd in view"     deny  "$(qv Bash command "curl -oQueue.md http://x" "$V")"
case_ "bash long brace word elsewhere"         allow "$(qv Bash command "cat {$(many 4100 'a'),x}" "$C")"
case_ "bash 9 brace lists elsewhere"           allow "$(qv Bash command "cat {,}{,}{,}{,}{,}{,}{,}{,}{,}x" "$C")"
case_ "bash sort -o other file, cwd in view"  allow "$(qv Bash command "sort -oOut.md /dev/null" "$V")"
case_ "bash sort -o attached elsewhere"        allow "$(qv Bash command "sort -oQueue.md /dev/null" "$C")"
case_ "bash lower-case name elsewhere"        allow "$(qv Bash command "cat queue.md" "$C")"
case_ "bash star glob elsewhere"               allow "$(qv Bash command "ls *.md" "$C")"
case_ "bash star glob under plans, cwd in view" allow "$(qv Bash command "ls plans/*.md" "$V")"
case_ "bash plans glob, cwd vault root"        allow "$(qv Bash command "wc -l projects/ClaudeOS/plans/*.md" "$R")"
case_ "bash projects listing, cwd vault root"  allow "$(qv Bash command "ls projects/*" "$R")"
case_ "bash other glob, cwd in view"           allow "$(qv Bash command "ls *.go" "$V")"
case_ "bash inbox by name, cwd in view"        allow "$(qv Bash command "cat Inbox.md" "$V")"
case_ "bash brace list elsewhere"              allow "$(qv Bash command "cat {Queue.md,README.md}" "$C/testdata")"
case_ "bash cd -- elsewhere"                   allow "$(qv Bash command "cd -- internal/queue && cat testdata/Queue.md" "$C")"
# --- reads: a bare reader on the view or the authority is allowed; a write spelling beside it, a wrapper or a redirect onto it is not
case_ "read cat absolute view"                 allow "$(qv Bash command "cat $V/Queue.md")"
case_ "read cat authority"                     allow "$(qv Bash command "cat $Q/Queue.md")"
case_ "read cat relative view"                 allow "$(qv Bash command "cat projects/ClaudeOS/Queue.md" "$R")"
case_ "read ls bare name, cwd in view"         allow "$(qv Bash command "ls Queue.md" "$V")"
case_ "read ls star glob, cwd in view"         allow "$(qv Bash command "ls *.md" "$V")"
case_ "read ls -la absolute view"              allow "$(qv Bash command "ls -la $V/Queue.md")"
case_ "read head, cwd in view"                 allow "$(qv Bash command "head -n 20 Queue.md" "$V")"
case_ "read tail dotdot name, cwd under view"  allow "$(qv Bash command "tail -5 ../Queue.md" "$V/plans")"
case_ "read wc absolute view"                  allow "$(qv Bash command "wc -l $V/Queue.md")"
case_ "read grep -n absolute view"             allow "$(qv Bash command "grep -n '^## ' $V/Queue.md")"
case_ "rg on the view"                         deny  "$(qv Bash command "rg -n 'q429' $V/Queue.md")"
case_ "read stat diff file cut nl"             allow "$(qv Bash command "stat $V/Queue.md; diff $V/Queue.md $Q/Queue.md; file $V/Queue.md; cut -c1-80 $V/Queue.md; nl $V/Queue.md")"
case_ "read cd into view"                      allow "$(qv Bash command "cd $V && cat Queue.md" "$C")"
case_ "read cd chain into view"                allow "$(qv Bash command "cd ~/obsidian/SecondBrain && cd projects/ClaudeOS && cat Queue.md" "$C")"
case_ "read cd quoted icloud view"             allow "$(qv Bash command "cd '$I' && cat Queue.md" "$C")"
case_ "read lower-case name, cwd in view"      allow "$(qv Bash command "cat queue.md" "$V")"
case_ "read quoted pieces, absolute"           allow "$(qv Bash command "cat \"$V\"/'Queue.md'")"
case_ "read brace list, cwd in view"           allow "$(qv Bash command "cat {Queue.md,Inbox.md}" "$V")"
case_ "read bare star, cwd in authority"       allow "$(qv Bash command "cat *" "$Q")"
case_ "read piped to a reader"                 allow "$(qv Bash command "cat $V/Queue.md | head -3")"
case_ "read piped to a writer"                 deny  "$(qv Bash command "cat $V/Queue.md | tee /tmp/out")"
case_ "read redirected elsewhere"              allow "$(qv Bash command "cat $V/Queue.md > /tmp/out 2>&1")"
case_ "read beside an unlisted program"        deny  "$(qv Bash command "cat $V/Queue.md; echo x >> /tmp/out")"
case_ "read input redirect from the view"      allow "$(qv Bash command "wc -l < $V/Queue.md")"
case_ "read then a write"                      deny  "$(qv Bash command "cat Queue.md; sed -i '' 's/a/b/' Queue.md" "$V")"
case_ "read then a move"                       deny  "$(qv Bash command "cat $V/Queue.md && mv $V/Queue.md /tmp/x")"
case_ "read redirected onto the view"          deny  "$(qv Bash command "cat $V/Inbox.md > $V/Queue.md")"
