case_ "git push --help"                      allow "$(pg "git push --help")"
case_ "git pull master"                      allow "$(pg "git pull origin master")"
case_ "git fetch master"                     allow "$(pg "git fetch origin master")"
case_ "git rebase onto master"               allow "$(pg "git rebase origin/master")"
case_ "git merge master"                     allow "$(pg "git merge origin/master")"
case_ "git switch master"                    allow "$(pg "git switch master")"
