case_ "set upstream to master"               allow "$(pg "git branch --set-upstream-to origin/master")"
case_ "rest read of master ref"              allow "$(pg "gh api repos/o/r/git/ref/heads/master")"
case_ "rest get of master refs"              allow "$(pg "gh api -X GET repos/o/r/git/refs/heads/master")"
case_ "rest delete of a feature ref"         allow "$(pg "gh api --method DELETE repos/o/r/git/refs/heads/q611-feature")"
case_ "graphql read of master"               allow "$(pg 'gh api graphql -f query="{ repository(owner:\"o\", name:\"r\") { ref(qualifiedName:\"refs/heads/master\") { target { oid } } } }"')"
