case_ "push guard bad input shape"           silent "$(printf 'garbage' | guard guard-push.sh | shape)"
case_ "push deny names make tag"             1     "$(payload PreToolUse Bash command "git push origin master" | guard guard-push.sh | grep -c 'make tag')"
case_ "quoted -c value with a space"         deny  "$(pg 'git -c "user.name=A B" push origin master' "$PF")"
case_ "escaped space in a -c value"          deny  "$(pg 'git -c user.name=A\ B push origin master' "$PF")"
case_ "quoted -C path with a space"          deny  "$(pg 'git -C "/path with space" push origin master' "$PF")"
case_ "push heads/master"                    deny  "$(pg "git push origin heads/master" "$PF")"
case_ "push HEAD:heads/master"               deny  "$(pg "git push origin HEAD:heads/master" "$PF")"
