if [[ -z ${GUARD_BASH:-} && -x /bin/bash ]]; then
  GUARD_BASH=/bin/bash "$0" | sed "s|^|[/bin/bash] |"
  (( PIPESTATUS[0] == 0 )) || fail=1
fi
exit $fail
